/**
 * THE DUBAI MUNICIPALITY SHEET — "Unified Site Plan", generated by Kharetati.
 *
 * The third generator on file, and the one the first two readers got least out
 * of. Of everything it prints they read the parcel id, the community and the
 * area; the client uploaded `updated affection plan.pdf` (plot 1341556, Al
 * Mamzar) and was told the sheet stated no land use, no height and no FAR, when
 * it states all three — in Arabic.
 *
 * WHAT IS DIFFERENT, AND WHAT EACH DIFFERENCE COST.
 *
 *   - THE CONTROLS ARE ARABIC, AND THEIR GLYPHS ARRIVE ONE AT A TIME, IN VISUAL
 *     ORDER. The table on the left (`Landuse`, `Height`, `Parking`, `Setback`,
 *     `Remarks`, each beside a zoning code such as `RC2/18`) is typeset in a font
 *     whose every letter is its own text item, laid out left to right as the eye
 *     sees them. Read in content order the land use is "ي ن ك س , ب ت ا ك م …".
 *     Read right to left, with a space wherever the ink leaves a gap, it is
 *     «تجاري, مكاتب, سكني». `rtlLine` does that, and nothing more: it does not
 *     reshape, normalise or translate, so the value the screen shows is the
 *     sheet's own words.
 *
 *   - THE SITE PLAN IS VECTOR. The Trakhees and DDA sheets place their drawing
 *     as one raster, and `site-plan.ts` fits a polygon to its pixels. Here the
 *     subject plot is a filled path — four corners, in page points, exact — and
 *     the six images on the page are the location maps around it. Running the
 *     raster reader on this sheet picked the largest of those maps and reported
 *     "0 pixels of the subject colour", which was true and useless.
 *
 *   - THE DRAWING HAS A SCALE AND A GRID. `Scale - 1 : 1400`, and four crosses
 *     labelled `501810E / 2798240N` … `501980E / 2798450N`. The crosses are what
 *     is read, not the scale note: two crosses 170 m apart in easting sit 343.67
 *     points apart, which is the scale, measured, in both axes independently —
 *     and on plot 1341556 it is 0.49466 m per point in x and 0.49468 in y, and
 *     the four boundaries it gives agree with the four dimensions the drawing
 *     prints (98.51, 174.18, 122.65, 17.22) to within 15 cm.
 *
 * WHAT IS CLAIMED, AND HOW STRONGLY.
 *
 *   The corners are the drawing's own vertices, positioned by the drawing's own
 *   grid. That is a reading of the document, and the legs and the area are
 *   published DERIVED — but only once the ring has reproduced the printed plot
 *   area, as the DDA survey table must. The NAME of the grid is not printed. The
 *   eastings sit on the 500,000 m false easting of Dubai Local Transverse
 *   Mercator (EPSG:3997), which is the grid Dubai Municipality issues in, and UTM
 *   40N would put the same numbers in Oman; that identification is the one
 *   inference in this module, and `system` is published ASSUMED with that basis.
 *   It moves where the plot is drawn on a map and nothing the engine computes.
 *
 *   What lies beyond each boundary is SUGGESTED, from the labels the drawing
 *   prints outside it — a road's name and width, a neighbour's plot number.
 *   FR-PLT-001 AC3 gives that field no default, so this module only reports
 *   the evidence. Since 16 Oct 2026 the studio fills an EMPTY field from it by
 *   itself, at Eng. Mohamed's request, with the evidence written beside the
 *   field and the reader free to change it (`apps/web-next/src/studio/edge-suggest.ts`).
 */

import { type TextItem, type PdfPageText } from './pdf-text.js';
import { type SurveyPoint } from './dda.js';

// ---------------------------------------------------------------------------
// Which sheet
// ---------------------------------------------------------------------------

/**
 * Does this page come from the Municipality's generator?
 *
 * Two markers of three, as `isDdaSheet` does it: the footer names the GIS
 * Center in Dubai Municipality, the disclaimer names Kharetati, and the header
 * carries a `DLD Ref Number` box neither of the other generators prints.
 */
export function isDmSheet(page: PdfPageText): boolean {
  const text = page.items.map((i) => i.text).join('\n');
  const markers = [/Dubai Municipality/i, /Kharetati/i, /DLD Ref Number/i];
  return markers.filter((m) => m.test(text)).length >= 2;
}

// ---------------------------------------------------------------------------
// Arabic, one glyph at a time
// ---------------------------------------------------------------------------

const ARABIC = /[؀-ۿݐ-ݿﭐ-﷿ﹰ-﻿]/;
const STRONG_LTR = /[A-Za-z0-9]/;
const MIRROR: Readonly<Record<string, string>> = { '(': ')', ')': '(', '[': ']', ']': '[', '{': '}', '}': '{', '<': '>', '>': '<' };

/** Wider than the space between two letters of one word, narrower than a word space. */
const WORD_GAP_PT = 1.2;
const LINE_BAND_PT = 3;

/**
 * One visual line, read right to left.
 *
 * Three kinds of run, three rules. An Arabic run is already in logical order
 * inside itself (`إل` arrives as `إل`), so it is kept. A Latin or numeric run —
 * `16`, `5.0`, `RC2/18` — reads left to right inside an Arabic sentence, so it is
 * kept too. A run of neutral marks such as `) +` was laid out in visual order
 * and has to be turned round, with its brackets mirrored, which is exactly what
 * a bidirectional renderer did to it on the way to the page.
 */
export function rtlLine(items: readonly TextItem[]): string {
  const ordered = [...items].sort((a, b) => b.bbox[0] - a.bbox[0]);
  let out = '';
  let left: number | undefined;
  for (const item of ordered) {
    const gap = left === undefined ? 0 : left - item.bbox[2];
    /* A two-letter Arabic item is a lam-alef LIGATURE — one glyph — and the
       font's map writes it alef first, so «الارتفاع» came out «االرتفاع». */
    const piece = LIGATURE.test(item.text)
      ? `ل${item.text[0] ?? ''}`
      : ARABIC.test(item.text) || STRONG_LTR.test(item.text)
      ? item.text
      : [...item.text].reverse().map((c) => MIRROR[c] ?? c).join('');
    if (out !== '' && gap > WORD_GAP_PT) out += ' ';
    out += piece;
    left = item.bbox[0];
  }
  const line = out.replace(/\s+/g, ' ').trim();
  // A comma inside an Arabic sentence is the Arabic comma, set against the word before it.
  return ARABIC.test(line) ? line.replace(/\s*,\s*/g, '، ') : line;
}

const LIGATURE = /^[اأإآ]ل$/;

/** Items grouped into visual lines, top line first. */
function lines(items: readonly TextItem[]): readonly (readonly TextItem[])[] {
  const rows: TextItem[][] = [];
  for (const item of [...items].sort((a, b) => b.bbox[1] - a.bbox[1])) {
    const row = rows.at(-1);
    const first = row?.[0];
    if (row && first && Math.abs(first.bbox[1] - item.bbox[1]) <= LINE_BAND_PT) row.push(item);
    else rows.push([item]);
  }
  return rows;
}

/** The box around a set of items, as one citable cell. */
function cell(items: readonly TextItem[], text: string, page: number): TextItem {
  return {
    text,
    page,
    bbox: [
      Math.min(...items.map((i) => i.bbox[0])),
      Math.min(...items.map((i) => i.bbox[1])),
      Math.max(...items.map((i) => i.bbox[2])),
      Math.max(...items.map((i) => i.bbox[3])),
    ],
  };
}

/** One row of the controls table: its zoning code and its Arabic value, line by line. */
export interface DmRow {
  /** `RC2/18`, the zoning code printed in the row, when there is one. */
  readonly code?: string;
  /** Each visual line, read right to left, top first. */
  readonly lines: readonly string[];
  /** The whole value as one citable cell. */
  readonly box: TextItem;
}

const ROW_LABELS = ['Landuse', 'Height', 'Parking', 'Setback', 'Remarks'] as const;
export type DmRowLabel = (typeof ROW_LABELS)[number];

/**
 * The controls table, row by row.
 *
 * Each row is bounded halfway to the label above and below it rather than by a
 * fixed height, because the Parking row runs to four lines and the Land use row
 * to one. The value is everything left of the row's zoning code; the code is
 * the nearest item left of the English label on the label's own baseline.
 */
export function readDmRows(page: PdfPageText): Partial<Record<DmRowLabel, DmRow>> {
  const labels = ROW_LABELS.map((l) => ({ label: l, item: page.items.find((i) => i.text.trim() === l) }))
    .filter((l): l is { label: DmRowLabel; item: TextItem } => l.item !== undefined)
    .sort((a, b) => b.item.bbox[1] - a.item.bbox[1]);
  const mid = (i: TextItem): number => (i.bbox[1] + i.bbox[3]) / 2;
  const out: Partial<Record<DmRowLabel, DmRow>> = {};
  labels.forEach(({ label, item }, k) => {
    const above = labels[k - 1];
    const below = labels[k + 1];
    const y = mid(item);
    const top = above ? (y + mid(above.item)) / 2 : y + 30;
    const bottom = below ? (y + mid(below.item)) / 2 : y - 30;
    const code = page.items
      .filter((i) => i.bbox[2] < item.bbox[0] && Math.abs(mid(i) - y) <= 6 && /\S/.test(i.text))
      .sort((a, b) => b.bbox[2] - a.bbox[2])[0];
    const edge = code ? code.bbox[0] - 2 : item.bbox[0] - 2;
    const values = page.items.filter((i) => {
      const m = mid(i);
      return i.bbox[2] <= edge && m < top && m >= bottom && i.text.trim() !== '';
    });
    if (values.length === 0) return;
    const read = lines(values).map(rtlLine).filter((l) => l !== '');
    out[label] = {
      ...(code ? { code: code.text.trim() } : {}),
      lines: read,
      box: cell(values, read.join(' / '), page.page),
    };
  });
  return out;
}

// ---------------------------------------------------------------------------
// The words of the rows
// ---------------------------------------------------------------------------

const ORDINAL: Readonly<Record<string, number>> = { أول: 1, ثاني: 2, ثالث: 3, رابع: 4, خامس: 5 };

/**
 * «أرضي + أول للقاعدة البرج + (16) طابق» — ground, one podium level, sixteen
 * tower floors: `G+1P+16` in the notation the other two generators print.
 *
 * Narrow, and it returns nothing rather than guessing: the podium count is an
 * ordinal or a numeral attached to «للقاعدة» (for the base), and the tower count
 * is the numeral before «طابق». A sentence of another shape is shown verbatim
 * and the height is left unread.
 */
export function parseArabicHeight(line: string): { podiumLevels: number; typicalFloors: number } | undefined {
  if (!/أرضي/.test(line)) return undefined;
  const tower = /\(?\s*(\d{1,3})\s*\)?\s*طابق/.exec(line);
  if (!tower?.[1]) return undefined;
  /* «للقاعدة» arrives with one lam: the font sets lam-lam as a single glyph and
     maps it to one letter. Both spellings are accepted rather than the word repaired. */
  const base = /(\d{1,2}|أول|ثاني|ثالث|رابع|خامس)\s*ل?لقاعدة/.exec(line);
  const podiumLevels = base?.[1] === undefined ? 0 : (ORDINAL[base[1]] ?? Number(base[1]));
  if (!Number.isInteger(podiumLevels)) return undefined;
  return { podiumLevels, typicalFloors: Number(tower[1]) };
}

/** «ونسبة طابقية = 5.0» — the floor area ratio, in the Municipality's words. */
export function parseArabicFar(line: string): string | undefined {
  return /نسبة\s*طابقية\s*=?\s*(\d+(?:\.\d+)?)/.exec(line)?.[1];
}

/** `Request Ref: SAPS-08082026-195370` — the day the sheet was generated, and its reference. */
export function readDmRequest(page: PdfPageText): { ref: string; date: string; item: TextItem } | undefined {
  for (const item of page.items) {
    const m = /SAPS-(\d{2})(\d{2})(\d{4})-\d+/.exec(item.text);
    if (m?.[1] && m[2] && m[3]) return { ref: m[0], date: `${m[1]}-${m[2]}-${m[3]}`, item };
  }
  return undefined;
}

// ---------------------------------------------------------------------------
// The drawing
// ---------------------------------------------------------------------------

type Pt = readonly [number, number];
type Matrix = readonly [number, number, number, number, number, number];

interface Path {
  readonly paint: number;
  readonly fill: string | null;
  readonly points: readonly Pt[];
  readonly closed: boolean;
}

interface PdfOps {
  readonly save: number;
  readonly restore: number;
  readonly transform: number;
  readonly constructPath: number;
  readonly setFillRGBColor: number;
  readonly fill: number;
  readonly eoFill: number;
  readonly fillStroke: number;
  readonly eoFillStroke: number;
  readonly closeFillStroke: number;
  readonly closeEOFillStroke: number;
  readonly stroke: number;
}

const multiply = (a: Matrix, b: Matrix): Matrix => [
  a[0] * b[0] + a[2] * b[1],
  a[1] * b[0] + a[3] * b[1],
  a[0] * b[2] + a[2] * b[3],
  a[1] * b[2] + a[3] * b[3],
  a[0] * b[4] + a[2] * b[5] + a[4],
  a[1] * b[4] + a[3] * b[5] + a[5],
];

/* pdfjs 5 hands a path over as one flat array: an opcode, then its points.
   moveTo and lineTo carry one point, curveTo three, quadraticCurveTo two,
   closePath none. A curve is kept as its end point — a chord — because the
   plots on file are drawn with Béziers whose control points sit on their ends,
   which is a straight line written the long way round. */
const DRAW = { moveTo: 0, lineTo: 1, curveTo: 2, quadraticCurveTo: 3, closePath: 4 } as const;
const TAKES: Readonly<Record<number, number>> = { 0: 2, 1: 2, 2: 6, 3: 4, 4: 0 };

/** Every path on the page, in page points, with the fill colour it was painted under. */
export function pagePaths(ops: { fnArray: number[]; argsArray: unknown[] }, OPS: PdfOps): readonly Path[] {
  const out: Path[] = [];
  const stack: Matrix[] = [];
  let ctm: Matrix = [1, 0, 0, 1, 0, 0];
  let fill: string | null = null;
  for (let i = 0; i < ops.fnArray.length; i += 1) {
    const fn = ops.fnArray[i];
    const args = ops.argsArray[i];
    if (fn === OPS.save) stack.push(ctm);
    else if (fn === OPS.restore) ctm = stack.pop() ?? [1, 0, 0, 1, 0, 0];
    else if (fn === OPS.transform && Array.isArray(args) && args.length >= 6) ctm = multiply(ctm, args as unknown as Matrix);
    else if (fn === OPS.setFillRGBColor && Array.isArray(args) && typeof args[0] === 'string') fill = args[0];
    else if (fn === OPS.constructPath && Array.isArray(args) && typeof args[0] === 'number' && Array.isArray(args[1])) {
      const data = args[1][0] as ArrayLike<number> | undefined;
      if (!data || typeof data.length !== 'number') continue;
      const points: Pt[] = [];
      let closed = false;
      let k = 0;
      while (k < data.length) {
        const op = data[k] ?? -1;
        k += 1;
        const take = TAKES[op];
        if (take === undefined) break;
        if (op === DRAW.closePath) closed = true;
        if (take > 0) {
          const x = data[k + take - 2] ?? 0;
          const y = data[k + take - 1] ?? 0;
          points.push([ctm[0] * x + ctm[2] * y + ctm[4], ctm[1] * x + ctm[3] * y + ctm[5]]);
        }
        k += take;
      }
      out.push({ paint: args[0], fill, points, closed });
    }
  }
  return out;
}

interface PdfJs {
  getDocument(src: Record<string, unknown>): {
    promise: Promise<{
      readonly numPages: number;
      getPage(n: number): Promise<{ getOperatorList(): Promise<{ fnArray: number[]; argsArray: unknown[] }> }>;
      destroy(): Promise<void>;
    }>;
  };
  readonly OPS: PdfOps;
}

/**
 * The first page's paths, opened as `site-plan.ts` opens the document: a copy
 * of the bytes (pdfjs neuters what it is handed) and the DOMMatrix shim first.
 */
export async function readDmDrawing(bytes: Uint8Array): Promise<{ paths: readonly Path[]; OPS: PdfOps }> {
  const { ensureDOMMatrix } = await import('./dom-matrix.js');
  ensureDOMMatrix();
  const mod = (await import('pdfjs-dist/legacy/build/pdf.mjs')) as unknown as PdfJs;
  const doc = await mod.getDocument({ data: Uint8Array.from(bytes), isEvalSupported: false }).promise;
  try {
    if (doc.numPages < 1) return { paths: [], OPS: mod.OPS };
    const page = await doc.getPage(1);
    return { paths: pagePaths(await page.getOperatorList(), mod.OPS), OPS: mod.OPS };
  } finally {
    await doc.destroy();
  }
}

export type { Path as DmPath, PdfOps as DmOps };

/** The subject plot's fill: the Municipality's orange, `#f6c567` on the sheets on file. */
function isSubjectFill(hex: string | null): boolean {
  if (!hex || !/^#[0-9a-f]{6}$/i.test(hex)) return false;
  const r = parseInt(hex.slice(1, 3), 16);
  const g = parseInt(hex.slice(3, 5), 16);
  const b = parseInt(hex.slice(5, 7), 16);
  return r >= 225 && g >= 165 && g <= 220 && b >= 60 && b <= 140;
}

function signedArea(ring: readonly Pt[]): number {
  let twice = 0;
  for (let i = 0; i < ring.length; i += 1) {
    const a = ring[i]!;
    const b = ring[(i + 1) % ring.length]!;
    twice += a[0] * b[1] - b[0] * a[1];
  }
  return twice / 2;
}

/** A ring without the repeated closing vertex and without zero-length steps. */
function tidy(points: readonly Pt[]): readonly Pt[] {
  const out: Pt[] = [];
  for (const p of points) {
    const last = out.at(-1);
    if (!last || Math.hypot(p[0] - last[0], p[1] - last[1]) > 0.01) out.push(p);
  }
  const first = out[0];
  const last = out.at(-1);
  if (first && last && out.length > 1 && Math.hypot(first[0] - last[0], first[1] - last[1]) <= 0.01) out.pop();
  return out;
}

/** The grid: page points to metres on the printed grid, one scale per axis. */
export interface DmGrid {
  readonly x0: number;
  readonly y0: number;
  readonly e0: number;
  readonly n0: number;
  /** Metres per point. */
  readonly sx: number;
  readonly sy: number;
  /** The labels it was read from, for the citation. */
  readonly box: TextItem;
}

const CROSS_ARM_PT: readonly [number, number] = [8, 40];

/**
 * The printed grid, read from its crosses and their labels.
 *
 * A cross is a horizontal and a vertical stroke of the same short length with a
 * shared midpoint. Each is paired with the nearest `nnnnnnE` and `nnnnnnnN`
 * label, and the scale is fitted on each axis separately. Refused — `undefined`
 * — unless there are two distinct crosses on each axis, every labelled cross
 * agrees with the fit to 0.5 m, and the two axes agree with each other to half a
 * percent: a drawing that is not north-up, or not to one scale, is not read as
 * one.
 */
export function readDmGrid(page: PdfPageText, paths: readonly Path[], stroke: number): DmGrid | undefined {
  const arms = paths
    .filter((p) => p.paint === stroke && p.points.length === 2)
    .map((p) => {
      const [a, b] = p.points as [Pt, Pt];
      return { a, b, len: Math.hypot(b[0] - a[0], b[1] - a[1]), mid: [(a[0] + b[0]) / 2, (a[1] + b[1]) / 2] as Pt };
    })
    .filter((s) => s.len >= CROSS_ARM_PT[0] && s.len <= CROSS_ARM_PT[1]);
  const horizontal = arms.filter((s) => Math.abs(s.a[1] - s.b[1]) < 0.01);
  const vertical = arms.filter((s) => Math.abs(s.a[0] - s.b[0]) < 0.01);
  const crosses: Pt[] = [];
  for (const h of horizontal) {
    if (vertical.some((v) => Math.hypot(v.mid[0] - h.mid[0], v.mid[1] - h.mid[1]) < 0.5 && Math.abs(v.len - h.len) < 0.5)) {
      crosses.push(h.mid);
    }
  }
  const eLabels = page.items.flatMap((i) => {
    const m = /^(\d{6}(?:\.\d+)?)\s*E$/.exec(i.text.trim());
    return m?.[1] ? [{ item: i, value: Number(m[1]) }] : [];
  });
  const nLabels = page.items.flatMap((i) => {
    const m = /^(\d{7}(?:\.\d+)?)\s*N$/.exec(i.text.trim());
    return m?.[1] ? [{ item: i, value: Number(m[1]) }] : [];
  });
  const centre = (i: TextItem): Pt => [(i.bbox[0] + i.bbox[2]) / 2, (i.bbox[1] + i.bbox[3]) / 2];
  const nearest = <T extends { item: TextItem }>(list: readonly T[], at: Pt, reach: number): T | undefined =>
    list
      .map((l) => ({ l, d: Math.hypot(centre(l.item)[0] - at[0], centre(l.item)[1] - at[1]) }))
      .filter((x) => x.d <= reach)
      .sort((a, b) => a.d - b.d)[0]?.l;

  const xs: { x: number; e: number }[] = [];
  const ys: { y: number; n: number }[] = [];
  const used: TextItem[] = [];
  for (const c of crosses) {
    const e = nearest(eLabels, c, 45);
    const n = nearest(nLabels, c, 60);
    if (!e || !n) continue;
    xs.push({ x: c[0], e: e.value });
    ys.push({ y: c[1], n: n.value });
    used.push(e.item, n.item);
  }
  const fit = <T>(pairs: readonly T[], at: (p: T) => number, value: (p: T) => number): { p0: number; v0: number; s: number } | undefined => {
    const sorted = [...pairs].sort((a, b) => at(a) - at(b));
    const lo = sorted[0];
    const hi = sorted.at(-1);
    if (!lo || !hi || at(hi) - at(lo) < 50) return undefined;
    const s = (value(hi) - value(lo)) / (at(hi) - at(lo));
    if (!(s > 0)) return undefined;
    const ok = sorted.every((p) => Math.abs(value(lo) + (at(p) - at(lo)) * s - value(p)) <= 0.5);
    return ok ? { p0: at(lo), v0: value(lo), s } : undefined;
  };
  const fx = fit(xs, (p) => p.x, (p) => p.e);
  const fy = fit(ys, (p) => p.y, (p) => p.n);
  if (!fx || !fy) return undefined;
  if (Math.abs(fx.s - fy.s) / fx.s > 0.005) return undefined;
  return {
    x0: fx.p0,
    y0: fy.p0,
    e0: fx.v0,
    n0: fy.v0,
    sx: fx.s,
    sy: fy.s,
    box: cell(used, used.map((u) => u.text.trim()).join(' · '), page.page),
  };
}

/** What one boundary is suggested to give onto, and the label that says so. */
export interface EdgeHint {
  readonly classification: 'ROAD' | 'ADJACENT_PLOT';
  readonly verbatim: string;
  /** How far outside the boundary the label sits, metres. */
  readonly distanceM: string;
}

/** The plot as the drawing places it, before it is traced. */
export interface DmPlot {
  readonly points: readonly SurveyPoint[];
  readonly areaM2: number;
  /** One per boundary, `points[i] → points[i+1]`; null where the drawing labels nothing outside it. */
  readonly hints: readonly (EdgeHint | null)[];
  /** The printed dimension nearest each boundary, metres, and what the drawing measures for it. */
  readonly dimensions: readonly ({ readonly printed: string; readonly measured: string } | null)[];
  readonly grid: DmGrid;
  /** The drawing frame the plot sits in, for the citation. */
  readonly box: TextItem;
}

/** How far outside a boundary a label may sit and still be about it: 60 m at 1:1400. */
const HINT_REACH_PT = 125;
const ROAD_LABEL = /^(?:SERVICE\s+)?(?:ROAD|SIKKA|STREET|ST\.?)\b.*$/i;
const PLOT_NUMBER = /^\d{6,8}$/;
const DIMENSION = /^(\d+\.\d{2})\s*\(/;

/**
 * The subject plot, its corners on the printed grid, and what lies beyond each boundary.
 *
 * Returns a sentence instead when the drawing cannot be read as one: no orange
 * fill, a fill that is not a ring, or a grid that does not hold together.
 */
export function readDmPlot(
  page: PdfPageText,
  paths: readonly Path[],
  OPS: PdfOps,
  parcelId: string | undefined,
): DmPlot | string {
  const fills = new Set([OPS.fill, OPS.eoFill, OPS.fillStroke, OPS.eoFillStroke, OPS.closeFillStroke, OPS.closeEOFillStroke]);
  const candidates = paths
    .filter((p) => fills.has(p.paint) && isSubjectFill(p.fill))
    .map((p) => tidy(p.points))
    .filter((r) => r.length >= 3)
    .sort((a, b) => Math.abs(signedArea(b)) - Math.abs(signedArea(a)));
  const ring = candidates[0];
  if (!ring) {
    return 'The drawing has no filled shape in the colour this generator gives the subject plot, so no corners are read from it.';
  }
  const grid = readDmGrid(page, paths, OPS.stroke);
  if (!grid) {
    return 'The drawing prints grid coordinates, but they do not resolve into one north-up scale — fewer than two labelled crosses on an axis, or crosses that disagree with each other — so the plot is not placed on the grid.';
  }

  const toGrid = (p: Pt): { e: number; n: number } => ({ e: grid.e0 + (p[0] - grid.x0) * grid.sx, n: grid.n0 + (p[1] - grid.y0) * grid.sy });
  const points: SurveyPoint[] = ring.map((p, i) => {
    const g = toGrid(p);
    return { id: String(i + 1), east: g.e.toFixed(3), north: g.n.toFixed(3) };
  });
  let twice = 0;
  for (let i = 0; i < points.length; i += 1) {
    const a = points[i]!;
    const b = points[(i + 1) % points.length]!;
    twice += Number(a.east) * Number(b.north) - Number(b.east) * Number(a.north);
  }

  // Outward is to the right of travel on an anticlockwise ring, to the left on a clockwise one.
  const ccw = signedArea(ring) > 0;
  const centre = (i: TextItem): Pt => [(i.bbox[0] + i.bbox[2]) / 2, (i.bbox[1] + i.bbox[3]) / 2];
  const place = (c: Pt, a: Pt, b: Pt): { t: number; out: number } => {
    const dx = b[0] - a[0];
    const dy = b[1] - a[1];
    const len = Math.hypot(dx, dy);
    const vx = c[0] - a[0];
    const vy = c[1] - a[1];
    const t = (vx * dx + vy * dy) / (len * len);
    const cross = (vx * dy - vy * dx) / len;
    return { t, out: ccw ? cross : -cross };
  };
  const scale = (grid.sx + grid.sy) / 2;

  const labels = page.items
    .map((i) => ({ item: i, text: i.text.replace(/\s+/g, ' ').trim() }))
    .filter((l) => ROAD_LABEL.test(l.text) || (PLOT_NUMBER.test(l.text) && l.text !== parcelId));
  const hints = ring.map((a, i) => {
    const b = ring[(i + 1) % ring.length]!;
    const near = labels
      .map((l) => ({ l, at: place(centre(l.item), a, b) }))
      .filter((x) => x.at.t > -0.05 && x.at.t < 1.05 && x.at.out > 0 && x.at.out <= HINT_REACH_PT)
      // A label belongs to the boundary it is nearest to, not to every one it is in reach of.
      .filter((x) =>
        ring.every((p, j) => {
          if (j === i) return true;
          const q = place(centre(x.l.item), p, ring[(j + 1) % ring.length]!);
          return !(q.t > -0.05 && q.t < 1.05 && q.out > 0 && q.out < x.at.out);
        }),
      );
    // A road outranks a neighbour: it is the label the setback and the access both read.
    const road = near.filter((x) => ROAD_LABEL.test(x.l.text)).sort((p, q) => p.at.out - q.at.out)[0];
    const plot = near.filter((x) => PLOT_NUMBER.test(x.l.text)).sort((p, q) => p.at.out - q.at.out)[0];
    const pick = road ?? plot;
    if (!pick) return null;
    return {
      classification: road ? ('ROAD' as const) : ('ADJACENT_PLOT' as const),
      verbatim: pick.l.text,
      distanceM: (pick.at.out * scale).toFixed(1),
    };
  });

  const dims = page.items.flatMap((i) => {
    const m = DIMENSION.exec(i.text.trim());
    return m?.[1] ? [{ item: i, metres: m[1] }] : [];
  });
  const dimensions = ring.map((a, i) => {
    const b = ring[(i + 1) % ring.length]!;
    const mid: Pt = [(a[0] + b[0]) / 2, (a[1] + b[1]) / 2];
    const hit = dims
      .map((d) => ({ d, dist: Math.hypot(centre(d.item)[0] - mid[0], centre(d.item)[1] - mid[1]) }))
      .filter((x) => x.dist <= 90)
      .sort((p, q) => p.dist - q.dist)[0];
    const pa = points[i]!;
    const pb = points[(i + 1) % points.length]!;
    const measured = Math.hypot(Number(pb.east) - Number(pa.east), Number(pb.north) - Number(pa.north));
    return hit ? { printed: hit.d.metres, measured: measured.toFixed(2) } : null;
  });

  const xs = ring.map((p) => p[0]);
  const ys = ring.map((p) => p[1]);
  return {
    points,
    areaM2: Math.abs(twice) / 2,
    hints,
    dimensions,
    grid,
    box: {
      text: `site plan drawing, subject plot (${ring.length} corners)`,
      page: page.page,
      bbox: [Math.min(...xs), Math.min(...ys), Math.max(...xs), Math.max(...ys)],
    },
  };
}
